1	package security
2	
3	import (
4		"sort"
5		"strconv"
6		"strings"
7	
8		"charm.land/lipgloss/v2"
9	
10		"github.com/anthnel/devdesk/internal/remediation"
11		"github.com/anthnel/devdesk/internal/scan"
12		"github.com/anthnel/devdesk/internal/ui/datatable"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// DEVDESK-754 (SC1, step 2): the pure half of "Group by fix". Nothing here
17	// touches the Model; the toggle, the level and the rendering live elsewhere.
18	
19	// groupKey identifies a group across two scans: what it is about, never its
20	// members or its target, so a re-scan finds the same row again.
21	type groupKey struct {
22		Ecosystem, Subject, Installed string
23		Unfixed                       bool
24	}
25	
26	// fixGroup is one row of the grouped list.
27	type fixGroup struct {
28		Key      groupKey
29		Severity scan.SeverityLevel
30		// Subject is the package, or the ID of a vulnerability that names none.
31		Subject string
32		// Change is the delta shown in the table, "1.1.1k -> 1.1.1w".
33		Change string
34		// Status is the Fix column, from fixStatusOf.
35		Status fixStatus
36		// Command is the group's command, "" when none is known or it is not plain
37		// words (scan.PlainWords).
38		Command string
39		// Members are every finding of the group, not only the visible ones.
40		Members []scan.Finding
41	}
42	
43	// cveGroups groups the vulnerabilities of findings by the cause that clears
44	// them, from remediation.GroupAll. Worst severity first, then the most
45	// findings, then Subject, then Change.
46	func cveGroups(findings []scan.Finding) []fixGroup {
47		fixes := remediation.GroupAll(findings)
48		groups := make([]fixGroup, 0, len(fixes))
49		for _, fx := range fixes {
50			if len(fx.Members) == 0 {
51				continue
52			}
53			g := fixGroup{
54				Key:      groupKey{Ecosystem: fx.Ecosystem, Subject: fx.Package, Installed: fx.Installed, Unfixed: fx.Unfixed},
55				Severity: fx.Severity,
56				Subject:  fx.Package,
57				Change:   fixChange(fx),
58				Status:   fixStatusOf(fx.Members[0], false),
59				Members:  fx.Members,
60			}
61			if fx.Command != "" && scan.PlainWords(fx.Command) {
62				g.Command = fx.Command
63			}
64			groups = append(groups, g)
65		}
66		sort.SliceStable(groups, func(i, j int) bool {
67			a, b := groups[i], groups[j]
68			if ra, rb := severityRank(a.Severity), severityRank(b.Severity); ra != rb {
69				return ra > rb
70			}
71			if len(a.Members) != len(b.Members) {
72				return len(a.Members) > len(b.Members)
73			}
74			if a.Subject != b.Subject {
75				return a.Subject < b.Subject
76			}
77			return a.Change < b.Change
78		})
79		return groups
80	}
81	
82	// fixChange is the delta of a fix: the installed version, an arrow and what it
83	// moves to. An unfixed group moves to none; versions that could not be ordered
84	// are all listed, none preferred.
85	func fixChange(fx remediation.Fix) string {
86		installed := fx.Installed
87		if installed == "" {
88			installed = "unknown"
89		}
90		switch {
91		case fx.Unfixed:
92			return installed + " -> none"
93		case fx.Target != "":
94			return installed + " -> " + fx.Target
95		}
96		var options []string
97		for _, o := range fx.Options {
98			for _, v := range strings.Split(o, ",") {
99				if v = strings.TrimSpace(v); v != "" {
100					options = append(options, v)
101				}
102			}
103		}
104		if len(options) == 0 {
105			return installed + " -> none"
106		}
107		return installed + " -> " + strings.Join(options, " or ")
108	}
109	
110	// findingIdentity is what sameFinding compares, as a map key.
111	type findingIdentity struct {
112		source, rule, file, pkg, version, instance string
113	}
114	
115	func identityOf(f scan.Finding) findingIdentity {
116		return findingIdentity{f.Source, remediation.RuleKey(f.ID), f.File, f.PkgName, f.Version, instanceOf(f)}
117	}
118	
119	// visibleGroups keeps the groups with at least one member in visible (matched
120	// by sameFinding), in the order of all. A kept group keeps all its members.
121	func visibleGroups(all []fixGroup, visible []scan.Finding) []fixGroup {
122		shown := make(map[findingIdentity]struct{}, len(visible))
123		for _, f := range visible {
124			shown[identityOf(f)] = struct{}{}
125		}
126		kept := make([]fixGroup, 0, len(all))
127		for _, g := range all {
128			for _, f := range g.Members {
129				if _, ok := shown[identityOf(f)]; ok {
130					kept = append(kept, g)
131					break
132				}
133			}
134		}
135		return kept
136	}
137	
138	// groupIndexOf is the index of the group that holds f, -1 if none.
139	func groupIndexOf(groups []fixGroup, f scan.Finding) int {
140		for i, g := range groups {
141			for _, member := range g.Members {
142				if sameFinding(member, f) {
143					return i
144				}
145			}
146		}
147		return -1
148	}
149	
150	// groupIndexByKey is the index of the group with key, else prev clamped into
151	// the list, -1 for an empty list.
152	func groupIndexByKey(groups []fixGroup, key groupKey, prev int) int {
153		for i, g := range groups {
154			if g.Key == key {
155				return i
156			}
157		}
158		return clampIndex(prev, len(groups))
159	}
160	
161	// clampIndex puts i into [0, n), -1 when n is 0.
162	func clampIndex(i, n int) int {
163		if n == 0 {
164			return -1
165		}
166		return max(0, min(i, n-1))
167	}
168	
169	// nearestFinding is the index in visible the findings cursor goes to when the
170	// grouped list is left (AC4): the first visible member of g, else prev if it is
171	// still visible, else prevCursor clamped into the list, -1 if visible is empty.
172	func nearestFinding(visible []scan.Finding, g *fixGroup, prev *scan.Finding, prevCursor int) int {
173		if len(visible) == 0 {
174			return -1
175		}
176		if g != nil && len(g.Members) > 0 {
177			for i, f := range visible {
178				for _, member := range g.Members {
179					if sameFinding(member, f) {
180						return i
181					}
182				}
183			}
184		}
185		if prev != nil {
186			for i, f := range visible {
187				if sameFinding(*prev, f) {
188					return i
189				}
190			}
191		}
192		return clampIndex(prevCursor, len(visible))
193	}
194	
195	// cveGroupColumns describes the grouped list of the CVE tab: Severity, Package,
196	// Change, CVEs, Fix. Cells are plain text (Rule 122); only Severity is coloured,
197	// and it is also its word.
198	func cveGroupColumns() []datatable.Column[fixGroup] {
199		return []datatable.Column[fixGroup]{
200			{
201				Title: "Severity", Sizing: datatable.SizingFixed, MinWidth: 10,
202				Cell:  func(g fixGroup) string { return string(g.Severity) },
203				Style: func(g fixGroup) lipgloss.Style { return theme.SeverityTextStyle(string(g.Severity)) },
204				Less:  func(a, b fixGroup) bool { return severityRank(a.Severity) < severityRank(b.Severity) },
205			},
206			{
207				Title: "Package", Sizing: datatable.SizingContent, MinWidth: 14,
208				Cell: func(g fixGroup) string { return g.Subject },
209				Less: func(a, b fixGroup) bool { return a.Subject < b.Subject },
210			},
211			{
212				Title: "Change", Sizing: datatable.SizingContent, MinWidth: 16, Flex: 1,
213				Cell: func(g fixGroup) string { return g.Change },
214				Less: func(a, b fixGroup) bool { return a.Change < b.Change },
215			},
216			{
217				Title: "CVEs", Sizing: datatable.SizingFixed, MinWidth: 5, DescFirst: true,
218				Cell: func(g fixGroup) string { return strconv.Itoa(len(g.Members)) },
219				Less: func(a, b fixGroup) bool { return len(a.Members) < len(b.Members) },
220			},
221			{
222				Title: "Fix", Sizing: datatable.SizingContent, MinWidth: 16, MaxWidth: 24, Optional: true,
223				Cell: func(g fixGroup) string { return g.Status.Label() },
224				Less: func(a, b fixGroup) bool { return a.Status.Label() < b.Status.Label() },
225			},
226		}
227	}
