17	// handleDetailsState processes input in details state
18	func (m Model) handleDetailsState(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
19		switch msg.String() {
20		// backspace was an alias of esc, and the only one in the application.
21		case "esc":
22			m.state = StateResults
23			m.changePreview = changePreview{}
24			return m, nil
25		case keymap.Web:
26			return m.handleDetailsOpenReference()
27		case "enter":
28			return m.openFindingFile()
29		case writeRemediationKey:
30			return m.prepareMisconfigFix()
31		case keymap.Copy:
32			return m.copyFixCommand()
33		case keymap.Exclude:
