69	// sizeDetails gives the details viewport the room the router leaves it: the
70	// view's width less the two border cells the viewport frame takes, so a line
71	// never reaches under the right border. The padding takes one more cell on each
72	// side, which is the text width (detailsTextWidth).
73	func (m *Model) sizeDetails() {
74		m.detailsViewport.SetWidth(max(m.width-2, 1))
75		m.detailsViewport.SetHeight(m.height)
