20	// The finding detail acts (DEVDESK-751). Its keys read the finding on screen
21	// (subjectFinding), never the table row behind it, and each one is decided by an
22	// availability the header and the handler share (Rule 130). DevDesk never runs
23	// the command under Run: Y copies it, and the user runs it.
24	
25	// reasonNoCommand is why Y is greyed: the finding has nothing to copy.
26	const reasonNoCommand = "This finding has no command to run"
27	
28	// writeClipboard is the clipboard write, a variable so a test can take it: the
29	// real one writes to the machine's clipboard. TestMain replaces it.
30	var writeClipboard = clipboard.WriteAll
31	
32	// FixCommandCopiedMsg reports the clipboard write of the command under Run
33	// (Rule 109).
34	type FixCommandCopiedMsg struct {
35		Command string
36		Err     error
37	}
