3	import (
4		"errors"
5		"io/fs"
6		"log"
7		"path/filepath"
8		"strings"
9	
10		tea "charm.land/bubbletea/v2"
11	
12		"github.com/anthnel/devdesk/internal/clipboard"
13		"github.com/anthnel/devdesk/internal/scan"
14		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
15		"github.com/anthnel/devdesk/internal/ui/shortcut"
16		uiviewer "github.com/anthnel/devdesk/internal/ui/viewer"
17		"github.com/anthnel/devdesk/internal/viewer"
18	)
19	
20	// The finding detail acts (DEVDESK-751). Its keys read the finding on screen
21	// (subjectFinding), never the table row behind it, and each one is decided by an
22	// availability the header and the handler share (Rule 130). DevDesk never runs
23	// the command under Run: Y copies it, and the user runs it.
24	
25	// reasonNoCommand is why Y is greyed: the finding has nothing to copy.
26	const reasonNoCommand = "This finding has no command to run"
27	
28	// writeClipboard is the clipboard write, a variable so a test can take it: the
29	// real one writes to the machine's clipboard. TestMain replaces it.
30	var writeClipboard = clipboard.WriteAll
31	
32	// FixCommandCopiedMsg reports the clipboard write of the command under Run
33	// (Rule 109).
34	type FixCommandCopiedMsg struct {
35		Command string
36		Err     error
37	}
38	
39	// subjectFinding is what a results or details action acts on: the finding on
40	// screen in the details state, the selected row in the results state. A re-scan
41	// puts the table back at the top, so the detail must never read the cursor.
42	func (m Model) subjectFinding() (scan.Finding, bool) {
43		switch m.state {
44		case StateDetails:
45			if m.selectedFinding == nil {
46				return scan.Finding{}, false
47			}
48			return *m.selectedFinding, true
49		case StateResults:
50			return m.findingsTable.Selected()
51		}
52		return scan.Finding{}, false
53	}
54	
55	// canOpenFindingFile says whether enter can open the subject's file. It looks at
56	// the path only: whether the file exists is for the viewer to say.
57	func (m Model) canOpenFindingFile() shortcut.Availability {
58		f, ok := m.subjectFinding()
59		if !ok {
60			return shortcut.Unavailable(reasonNoFinding)
61		}
62		_, a := findingFilePath(f, m.targetPath, m.targetOnDisk())
63		return a
64	}
65	
66	// canCopyFixCommand says whether Y has a command to copy: the one under Run, else
67	// the Repro line.
68	func (m Model) canCopyFixCommand() shortcut.Availability {
69		f, ok := m.subjectFinding()
70		if !ok {
71			return shortcut.Unavailable(reasonNoFinding)
72		}
73		_, a := copyCommand(f)
74		return a
75	}
76	
77	// FindingFileRefusedMsg reports that enter did not open the finding's file, and
78	// why (Rule 109).
79	type FindingFileRefusedMsg struct{ Reason string }
80	
81	// openFindingFile asks the router to open the subject's file in the viewer. The
82	// Cmd follows the links of the path first (findingFilePath only reads it): a
83	// link that leaves the scanned directory is refused with a reason.
84	func (m Model) openFindingFile() (tea.Model, tea.Cmd) {
85		if a := m.canOpenFindingFile(); !a.Enabled() {
86			return m, m.footer.Warn(a.Reason)
87		}
88		f, _ := m.subjectFinding()
89		path, _ := findingFilePath(f, m.targetPath, m.targetOnDisk())
90		root := m.targetPath
91		return m, func() tea.Msg {
92			if !staysInside(root, path) {
93				return FindingFileRefusedMsg{Reason: reasonFileLinkOutsideTarget}
94			}
95			return uiviewer.OpenRequestMsg{Source: viewer.NewFileSource(path)}
96		}
97	}
98	
99	// staysInside says whether path, with every link on it followed, is still under
100	// root, with every link on it followed too. A part of the path that does not
101	// exist is not a link: the existing part is resolved and the rest kept, so a
102	// missing file is still for the viewer to report. A path or a root that cannot be
103	// resolved for another reason (a permission, a loop of links) is refused: what is
104	// not resolved is not proven to stay inside (DEVDESK-753).
105	func staysInside(root, path string) bool {
106		realRoot, err := filepath.EvalSymlinks(filepath.Clean(root))
107		if err != nil {
108			return false
109		}
110		realPath, err := evalExisting(path)
111		if err != nil {
112			return false
113		}
114		rel, err := filepath.Rel(realRoot, realPath)
115		return err == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
116	}
117	
118	// evalExisting is filepath.EvalSymlinks on the longest existing prefix of path,
119	// followed by what does not exist.
120	func evalExisting(path string) (string, error) {
121		resolved, err := filepath.EvalSymlinks(path)
122		if err == nil || !errors.Is(err, fs.ErrNotExist) {
123			return resolved, err
124		}
125		parent := filepath.Dir(path)
126		if parent == path {
127			return path, nil
128		}
129		resolved, err = evalExisting(parent)
130		if err != nil {
131			return "", err
132		}
133		return filepath.Join(resolved, filepath.Base(path)), nil
134	}
135	
136	// copyFixCommand puts the command under Run, or else the Repro line, on the
137	// clipboard, whole. It never runs it. The command is copied into the Cmd
138	// (Rule 110).
139	func (m Model) copyFixCommand() (tea.Model, tea.Cmd) {
140		if a := m.canCopyFixCommand(); !a.Enabled() {
141			return m, m.footer.Warn(a.Reason)
142		}
143		f, _ := m.subjectFinding()
144		command, _ := copyCommand(f)
145		return m, func() tea.Msg {
146			return FixCommandCopiedMsg{Command: command, Err: writeClipboard(command)}
147		}
148	}
149	
150	// handleFixCommandCopied reports the clipboard write: a notice on success, an
151	// error without its cause on failure (Rule 128).
152	func (m Model) handleFixCommandCopied(msg FixCommandCopiedMsg) (tea.Model, tea.Cmd) {
153		if msg.Err != nil {
154			log.Printf("ERROR [security] copy command: %v", msg.Err)
155			return m, m.footer.Error("Failed to copy the command — check logs")
156		}
157		return m, m.footer.Info("Command copied to the clipboard")
158	}
159	
160	// refreshDetails rebuilds the detail on the result just put on screen, or closes
161	// it when the finding is gone. It reports whether the detail is still open. The
162	// reason a detail closes is already in the footer: the verdict that brought the
163	// result says the rule is cleared, or still reported.
164	func (m *Model) refreshDetails() bool {
165		if m.state != StateDetails {
166			return false
167		}
168		if m.selectedFinding != nil && m.result != nil {
169			for _, f := range m.result.Findings {
170				if sameFinding(f, *m.selectedFinding) {
171					m.selectedFinding = &f
172					m.detailsViewport.SetContent(m.buildDetailsContent())
173					return true
174				}
175			}
176		}
177		m.state = StateResults
178		m.selectedFinding = nil
179		return false
180	}
181	
182	// verifyingStatus is the footer status while a fix waits on its re-scan: a state
183	// of the screen with the shared activity dot, derived on every frame and gone
184	// with the verdict. Only the target being verified says it.
185	func (m Model) verifyingStatus() (sharedcomponents.Status, bool) {
186		if v := m.misconfigVerifying; v == nil || v.Target != m.targetPath {
187			return sharedcomponents.Status{}, false
188		}
189		return sharedcomponents.Status{Text: "Re-scanning to confirm the fix...", Activity: true}, true
190	}
