14	
15	// DEVDESK-754 (SC1, step 2): the pure half of "Group by fix" on the CVE tab.
16	
17	// cve builds a vulnerability finding.
18	func cve(id, pkg, eco, installed, fixed string, sev scan.SeverityLevel) scan.Finding {
19		class := scan.ClassLangPackages
20		if eco == "alpine" || eco == "debian" {
21			class = scan.ClassOSPackages
22		}
23		return scan.Finding{
24			ID: id, Title: id + " title", Source: scan.SourceTrivy, Severity: sev,
25			PkgName: pkg, Ecosystem: eco, Class: class, Version: installed, FixedIn: fixed,
26		}
27	}
28	
29	func groupBySubject(t *testing.T, groups []fixGroup, subject string) fixGroup {
30		t.Helper()
31		for _, g := range groups {
32			if g.Subject == subject {
33				return g
34			}
35		}
36		t.Fatalf("no group for %q in %+v", subject, groups)
37		return fixGroup{}
38	}
39	
40	func ids(fs []scan.Finding) []string {
41		out := make([]string, 0, len(fs))
42		for _, f := range fs {
43			out = append(out, f.ID)
44		}
45		return out
46	}
47	
48	func TestCVEGroups(t *testing.T) {
49		const (
50			crit = scan.SeverityCritical
51			high = scan.SeverityHigh
52			low  = scan.SeverityLow
53		)
54		cases := []struct {
55			name     string
56			findings []scan.Finding
57			subject  string
58			check    func(t *testing.T, g fixGroup)
59		}{
60			{
61				name: "three CVEs of one package are one row with the delta and the count",
62				findings: []scan.Finding{
63					cve("CVE-1", "openssl", "alpine", "1.1.1k", "1.1.1w", high),
64					cve("CVE-2", "openssl", "alpine", "1.1.1k", "1.1.1w", crit),
65					cve("CVE-3", "openssl", "alpine", "1.1.1k", "1.1.1w", low),
66				},
67				subject: "openssl",
68				check: func(t *testing.T, g fixGroup) {
69					if g.Change != "1.1.1k -> 1.1.1w" {
70						t.Errorf("Change = %q", g.Change)
71					}
72					if len(g.Members) != 3 {
73						t.Errorf("Members = %v, want the 3 CVEs", ids(g.Members))
74					}
75					if g.Severity != crit {
76						t.Errorf("Severity = %q, want the worst", g.Severity)
77					}
78					if g.Status.State != fixManual || g.Status.Label() != "Manual" {
79						t.Errorf("Status = %+v (%q), want Manual", g.Status, g.Status.Label())
80					}
81					if g.Command != "apk upgrade openssl" {
82						t.Errorf("Command = %q", g.Command)
83					}
84				},
85			},
