		"golang.org/x/net": `HIGH\s+golang\.org/x/net\s+0\.10\.0 -> 0\.23\.0\s+1\s+Manual`,
		"zlib":             `MEDIUM\s+zlib\s+1\.2 -> none\s+2\s+No fix published`,
		"libfoo":           `LOW\s+libfoo\s+1\.0\.0 -> abc or def\s+1\s+Manual`,
	}
